<template><main class="admin-content"><div class="mb-6 flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-black uppercase tracking-wider text-rose-600">SuperAdmin</p><h1 class="text-3xl font-black">Accounting Period Close</h1><p class="text-slate-500">Review and lock completed accounting periods. Australian financial years run 1 July to 30 June.</p></div><NuxtLink to="/admin/accounting" class="btn-secondary">← Accounting</NuxtLink></div>
<div v-if="err" class="mb-4 rounded-lg bg-red-50 p-3 text-red-700">{{err}}</div><div v-if="ok" class="mb-4 rounded-lg bg-emerald-50 p-3 text-emerald-700">{{ok}}</div>
<section class="admin-panel p-5"><div class="flex flex-wrap items-end gap-3"><label><span>Preset</span><select v-model="preset" @change="applyPreset" class="field"><option value="fy2026">2025–26 Financial Year</option><option value="fy2027">2026–27 Financial Year</option><option value="month">Current Month</option><option value="custom">Custom</option></select></label><label><span>From</span><input v-model="form.start_date" type="date" class="field" @change="preset='custom'"/></label><label><span>To</span><input v-model="form.end_date" type="date" class="field" @change="preset='custom'"/></label><button class="btn-secondary" @click="runChecks">Run Pre-close Checks</button></div></section>
<section class="mt-5 grid gap-4 md:grid-cols-4"><div class="metric"><small>Unposted Journals</small><b>{{checks?.unposted_journals ?? '—'}}</b></div><div class="metric"><small>Unreconciled Bank Items</small><b>{{checks?.unreconciled_bank_transactions ?? '—'}}</b></div><div class="metric"><small>Outstanding Receivables</small><b>{{money(checks?.outstanding_receivables)}}</b></div><div class="metric"><small>Outstanding Payables</small><b>{{money(checks?.outstanding_payables)}}</b></div></section>
<section class="admin-panel mt-5 p-5"><h2 class="text-xl font-black">Close Period</h2><p class="mt-1 text-sm text-slate-500">Closing prevents any new posted journal dated inside this range. Outstanding receivables/payables may remain open and are shown as warnings.</p><div class="mt-4 grid gap-3 md:grid-cols-2"><label><span>Period name</span><input v-model="form.name" class="field"/></label><label><span>Notes</span><input v-model="form.notes" class="field" placeholder="Optional close notes"/></label></div><div class="mt-4 rounded-xl border p-4" :class="checks?.can_close ? 'border-emerald-200 bg-emerald-50':'border-amber-200 bg-amber-50'"><b>{{checks?.can_close ? 'Ready to close' : 'Run checks / resolve blocking items'}}</b><p class="mt-1 text-sm">Unreconciled bank items and unpaid invoices/bills are warnings for review. Unposted journals block the close.</p></div><button class="btn-danger mt-4" :disabled="busy||!checks?.can_close" @click="closePeriod">🔒 Close & Lock Period</button></section>
<section class="admin-panel mt-5 p-5"><div class="flex items-center justify-between"><div><h2 class="text-xl font-black">Period History</h2><p class="text-sm text-slate-500">Closed and reopened accounting periods.</p></div><button class="btn-secondary" @click="loadPeriods">Refresh</button></div><div class="mt-4 overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b text-left"><th class="p-2">Period</th><th>Dates</th><th>Status</th><th>Closed</th><th class="text-right">Action</th></tr></thead><tbody><tr v-for="p in periods" :key="p.id" class="border-b"><td class="p-2 font-bold">{{p.name}}</td><td>{{date(p.start_date)}} – {{date(p.end_date)}}</td><td><span class="badge" :class="p.status==='closed'?'bg-rose-100 text-rose-700':'bg-amber-100 text-amber-700'">{{p.status}}</span></td><td>{{dateTime(p.closed_at)}}</td><td class="text-right"><button v-if="p.status==='closed'" class="btn-secondary" @click="reopen(p)">Reopen</button></td></tr><tr v-if="!periods.length"><td colspan="5" class="p-6 text-center text-slate-500">No periods have been closed yet.</td></tr></tbody></table></div></section></main></template>
<script setup lang="ts">definePageMeta({layout:'admin',middleware:['admin']});const{adminFetch,isSuperAdmin}=useAdminFetch();const periods=ref<any[]>([]),checks=ref<any>(null),err=ref(''),ok=ref(''),busy=ref(false),preset=ref('fy2027');const form=reactive({name:'2026–27 Financial Year',start_date:'2026-07-01',end_date:'2027-06-30',period_type:'financial_year',notes:''});const money=(v:any)=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(Number(v||0));const date=(v:any)=>v?new Date(String(v)+'T00:00:00').toLocaleDateString('en-AU'):'—';const dateTime=(v:any)=>v?new Date(v).toLocaleString('en-AU'):'—';function applyPreset(){const now=new Date();if(preset.value==='fy2026')Object.assign(form,{name:'2025–26 Financial Year',start_date:'2025-07-01',end_date:'2026-06-30',period_type:'financial_year'});else if(preset.value==='fy2027')Object.assign(form,{name:'2026–27 Financial Year',start_date:'2026-07-01',end_date:'2027-06-30',period_type:'financial_year'});else if(preset.value==='month'){const y=now.getFullYear(),m=String(now.getMonth()+1).padStart(2,'0'),last=new Date(y,now.getMonth()+1,0).getDate();Object.assign(form,{name:now.toLocaleString('en-AU',{month:'long',year:'numeric'}),start_date:`${y}-${m}-01`,end_date:`${y}-${m}-${last}`,period_type:'month'});}checks.value=null}async function loadPeriods(){try{periods.value=await adminFetch('/api/admin/accounting/periods')}catch(e:any){err.value=e?.data?.statusMessage||e.message}}async function runChecks(){err.value='';ok.value='';try{checks.value=await adminFetch(`/api/admin/accounting/periods/checks?from=${form.start_date}&to=${form.end_date}`)}catch(e:any){err.value=e?.data?.statusMessage||e.message}}async function closePeriod(){if(!confirm(`Close ${form.name}? New accounting postings dated ${form.start_date} to ${form.end_date} will be blocked.`))return;busy.value=true;err.value='';try{await adminFetch('/api/admin/accounting/periods/close',{method:'POST',body:form});ok.value=`${form.name} is now closed and locked.`;checks.value=null;await loadPeriods()}catch(e:any){err.value=e?.data?.statusMessage||e.message}finally{busy.value=false}}async function reopen(p:any){const reason=prompt(`Reason for reopening ${p.name}:`);if(!reason?.trim())return;try{await adminFetch('/api/admin/accounting/periods/reopen',{method:'POST',body:{id:p.id,reason}});ok.value=`${p.name} has been reopened.`;await loadPeriods()}catch(e:any){err.value=e?.data?.statusMessage||e.message}}onMounted(async()=>{if(!isSuperAdmin.value)return navigateTo('/admin');await loadPeriods();await runChecks()});</script>
<style scoped>.admin-panel{@apply rounded-xl border border-slate-200 bg-white shadow-sm}.metric{@apply rounded-xl border border-slate-200 bg-white p-5 shadow-sm}.metric small{@apply block text-xs font-bold uppercase tracking-wide text-slate-500}.metric b{@apply mt-2 block text-2xl font-black}.field{@apply mt-1 w-full rounded-lg border border-slate-300 bg-white px-3 py-2}.btn-secondary{@apply rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-bold hover:bg-slate-50}.btn-danger{@apply rounded-lg bg-rose-600 px-4 py-2 text-sm font-black text-white hover:bg-rose-700 disabled:cursor-not-allowed disabled:opacity-50}.badge{@apply inline-flex rounded-full px-2.5 py-1 text-xs font-black}label span{@apply block text-xs font-bold text-slate-600}</style>
